const listLeads = `-- name: ListLeads :many
SELECT
  l.id, l.full_name, l.phone, l.email, l.date_of_birth, l.gender, l.address, l.source, l.source_detail, l.utm_source, l.utm_medium, l.utm_campaign, l.utm_content, l.utm_term, l.interested_course_id, l.notes, l.pipeline_status, l.assigned_to, l.assigned_at, l.assigned_by, l.converted_student_id, l.converted_at, l.converted_by, l.created_by, l.created_at, l.updated_at, l.deleted_at,
  c.code AS course_code,
  c.name AS course_name,
  u_assignee.email AS assigned_to_email,
  sp.student_code AS converted_student_code,
  sp.full_name AS converted_student_name,
  sp.status AS converted_student_status
FROM leads l
LEFT JOIN courses c ON c.id = l.interested_course_id
LEFT JOIN users u_assignee ON u_assignee.id = l.assigned_to
LEFT JOIN student_profiles sp ON sp.id = l.converted_student_id
WHERE l.deleted_at IS NULL
AND (
  $1::text = ''
  OR l.full_name ILIKE '%' || $1 || '%'
  OR COALESCE(l.phone, '') ILIKE '%' || $1 || '%'
  OR COALESCE(l.email::text, '') ILIKE '%' || $1 || '%'
)
AND (
  $2::lead_pipeline_status IS NULL
  OR l.pipeline_status = $2
)
AND (
  $3::lead_source IS NULL
  OR l.source = $3
)
AND (
  $4::uuid IS NULL
  OR l.assigned_to = $4::uuid
)
AND (
  $5::timestamptz IS NULL
  OR l.created_at >= $5::timestamptz
)
AND (
  $6::timestamptz IS NULL
  OR l.created_at <= $6::timestamptz
)
ORDER BY
  CASE WHEN $7::text = 'full_name' AND $8::text = 'asc' THEN l.full_name END ASC,
  CASE WHEN $7::text = 'full_name' AND $8::text = 'desc' THEN l.full_name END DESC,
  CASE WHEN $7::text = 'created_at' AND $8::text = 'asc' THEN l.created_at END ASC,
  CASE WHEN $7::text = 'created_at' AND $8::text = 'desc' THEN l.created_at END DESC,
  l.created_at DESC,
  l.id DESC
LIMIT $10 OFFSET $9
`

