const listSaleStaff = `-- name: ListSaleStaff :many
SELECT DISTINCT
  u.id,
  u.email
FROM users u
JOIN user_roles ur ON ur.user_id = u.id
JOIN roles r ON r.id = ur.role_id
WHERE r.code IN ('SALE', 'SALE_ADMIN', 'ADMIN') AND u.status = 'active'
ORDER BY u.email ASC
`

type ListSaleStaffRow struct {
	ID    pgtype.UUID `json:"id"`
	Email string      `json:"email"`
}

func (q *Queries) ListSaleStaff(ctx context.Context) ([]ListSaleStaffRow, error) {
	rows, err := q.db.Query(ctx, listSaleStaff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSaleStaffRow{}
	for rows.Next() {
		var i ListSaleStaffRow
		if err := rows.Scan(&i.ID, &i.Email); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

